import memfs from 'memfs'
import { createConsoleLogger, NowConfig, FileSystem, GUID, type Telemetry } from '@servicenow/sdk-build-core'
import { Orchestrator, Project } from '../../src'
import { MockConnector } from './mock-connector'

// Mock the checkModuleExists function to control collision detection
jest.mock('@servicenow/sdk-build-plugins', () => ({
    ...jest.requireActual('@servicenow/sdk-build-plugins'),
    checkModuleExists: jest.fn().mockImplementation((modulePath: string) => {
        return modulePath === '@servicenow/glide/sn_cc'
    }),
}))

describe('Orchestrator.types Test Suite', () => {
    const logger = createConsoleLogger()
    let telemetry: Telemetry

    beforeEach(() => {
        jest.clearAllMocks()
        telemetry = {
            sendEvent: jest.fn(),
            error: jest.fn(),
            startTimerEvent: jest.fn().mockReturnValue({
                end: jest.fn().mockReturnValue({ name: 'dependencies', data: {} }),
            }),
        } as unknown as Telemetry
    })

    test('downloads d.ts script definition files', async () => {
        const vol = new memfs.Volume()
        const fs = memfs.createFsFromVolume(vol) as FileSystem

        const project = new Project({
            fileSystem: fs as FileSystem,
            logger,
            rootDir: '/',
            config: NowConfig.parse({ scope: 'x_test', scopeId: GUID() }, logger),
            telemetryClient: telemetry,
        })

        const orchestrator = new Orchestrator(
            project,
            new MockConnector({
                syntaxEditorCompletionDefinitions: () => Promise.resolve(`declare class GlideRecord {}`),
                syntaxEditorCacheScriptIncludes: () => Promise.resolve({}),
            })
        )

        await orchestrator.types()

        expect(telemetry.startTimerEvent).toHaveBeenCalledWith('dependencies')
        expect(telemetry.sendEvent).toHaveBeenCalled()
        expect(telemetry.error).not.toHaveBeenCalled()

        const config = project.getConfig()

        const { typesDir } = config
        const serverDts = project.resolvePath(typesDir, 'glide.server.d.ts')
        expect(FileSystem.existsSync(fs, serverDts)).toBeTruthy()
        const clientFile = fs.readFileSync(serverDts, { encoding: 'utf-8' })
        expect(clientFile).toBeDefined()
        expect(clientFile).toContain('declare class GlideRecord {}')

        const clientDts = project.resolvePath(typesDir, 'glide.client.d.ts')
        expect(FileSystem.existsSync(fs, clientDts)).toBeTruthy()
        const clientFileContent = fs.readFileSync(clientDts, { encoding: 'utf-8' })
        expect(clientFileContent).toBeDefined()
        expect(clientFileContent).toContain('g_form')
    })

    test('downloads server script include definitions', async () => {
        const vol = memfs.Volume.fromJSON({
            '/src/fluent/si.server.js': `function sample() { global.JSUtil(); }`,
        })
        const fs = memfs.createFsFromVolume(vol) as FileSystem

        const project = new Project({
            fileSystem: fs as FileSystem,
            logger,
            rootDir: '/',
            config: NowConfig.parse({ scope: 'x_test', scopeId: GUID() }, logger),
            telemetryClient: telemetry,
        })

        const orchestrator = new Orchestrator(
            project,
            new MockConnector({
                syntaxEditorCompletionDefinitions: () => Promise.resolve(`declare class GlideRecord {}`),
                syntaxEditorCacheScriptIncludes: () =>
                    Promise.resolve({
                        'global.JSUtil': '1e2e4e24c1af42bea7f0c0f9fa40fbeb',
                    }),
                syntaxEditorDefinitionsScriptIncludes: () =>
                    Promise.resolve({
                        '1e2e4e24c1af42bea7f0c0f9fa40fbeb': 'declare class JSUtil{  }',
                    }),
            })
        )

        await orchestrator.types()

        expect(telemetry.startTimerEvent).toHaveBeenCalledWith('dependencies')
        expect(telemetry.sendEvent).toHaveBeenCalled()
        expect(telemetry.error).not.toHaveBeenCalled()

        const config = project.getConfig()

        const { typesDir } = config

        const serverDts = project.resolvePath(typesDir, 'script-includes.server.d.ts')
        expect(FileSystem.existsSync(fs, serverDts)).toBeTruthy()
        const serverFileContent = fs.readFileSync(serverDts, { encoding: 'utf-8' })
        expect(serverFileContent).toBeDefined()
        expect(serverFileContent).toContain('JSUtil')
    })

    test('downloads script include definitions for modules based on the imports', async () => {
        const vol = memfs.Volume.fromJSON({
            '/src/fluent/si.server.js': `function sample() { global.JSUtil(); }`,
            '/src/server/script.ts': `
                import { ApplicationUtil } from '@servicenow/glide/x_snc_apputil';

                export function some() {
                    const appUtil = new ApplicationUtil();
                    appUtil.getApplicationName();
                }
            `,
        })
        const fs = memfs.createFsFromVolume(vol) as FileSystem

        const project = new Project({
            fileSystem: fs as FileSystem,
            logger,
            rootDir: '/',
            config: NowConfig.parse({ scope: 'x_test', scopeId: GUID() }, logger),
            telemetryClient: telemetry,
        })

        const orchestrator = new Orchestrator(
            project,
            new MockConnector({
                syntaxEditorCompletionDefinitions: () => Promise.resolve(`declare class GlideRecord {}`),
                syntaxEditorCacheScriptIncludes: () =>
                    Promise.resolve({
                        'x_snc_apputil.ApplicationUtil': '1e2e4e24c1af42bea7f0c0f9fa40fbeb',
                    }),
                syntaxEditorDefinitionsScriptIncludes: () =>
                    Promise.resolve({
                        '1e2e4e24c1af42bea7f0c0f9fa40fbeb': 'declare class ApplicationUtil{ initialize() }',
                    }),
            })
        )

        await orchestrator.types()

        expect(telemetry.startTimerEvent).toHaveBeenCalledWith('dependencies')
        expect(telemetry.sendEvent).toHaveBeenCalled()
        expect(telemetry.error).not.toHaveBeenCalled()

        const config = project.getConfig()

        const { typesDir } = config

        const serverDts = project.resolvePath(typesDir, 'script-includes.modules.d.ts')
        expect(FileSystem.existsSync(fs, serverDts)).toBeTruthy()
        const serverFileContent = fs.readFileSync(serverDts, { encoding: 'utf-8' })
        expect(serverFileContent).toBeDefined()
        expect(serverFileContent).toMatchInlineSnapshot(`
"declare module '@servicenow/glide/x_snc_apputil' {
    class ApplicationUtil {
        initialize();
    }
}

"
`)
    })

    test('downloads global script include definitions for modules based property access experession', async () => {
        const vol = memfs.Volume.fromJSON({
            '/src/fluent/si.server.js': `function sample() { global.JSUtil(); }`,
            '/src/server/script.ts': `
                import { global } from '@servicenow/glide/global';

                export function some() {
                    const appUtil = new global.Util();
                    appUtil.getApplicationName();
                }
            `,
        })
        const fs = memfs.createFsFromVolume(vol) as FileSystem

        const project = new Project({
            fileSystem: fs as FileSystem,
            logger,
            rootDir: '/',
            config: NowConfig.parse({ scope: 'x_test', scopeId: GUID() }, logger),
            telemetryClient: telemetry,
        })

        const orchestrator = new Orchestrator(
            project,
            new MockConnector({
                syntaxEditorCompletionDefinitions: () => Promise.resolve(`declare class GlideRecord {}`),
                syntaxEditorCacheScriptIncludes: () =>
                    Promise.resolve({
                        'global.Util': '1e2e4e24c1af42bea7f0c0f9fa40fbeb',
                    }),
                syntaxEditorDefinitionsScriptIncludes: () =>
                    Promise.resolve({
                        '1e2e4e24c1af42bea7f0c0f9fa40fbeb': 'declare class Util{ initialize() }',
                    }),
            })
        )

        await orchestrator.types()

        expect(telemetry.startTimerEvent).toHaveBeenCalledWith('dependencies')
        expect(telemetry.sendEvent).toHaveBeenCalled()
        expect(telemetry.error).not.toHaveBeenCalled()

        const config = project.getConfig()

        const { typesDir } = config

        const serverDts = project.resolvePath(typesDir, 'script-includes.modules.d.ts')
        expect(FileSystem.existsSync(fs, serverDts)).toBeTruthy()
        const serverFileContent = fs.readFileSync(serverDts, { encoding: 'utf-8' })
        expect(serverFileContent).toBeDefined()
        expect(serverFileContent).toMatchInlineSnapshot(`
"declare module '@servicenow/glide/global' {
    namespace global {
        class Util {
            initialize();
        }
    }
}

"
`)
    })

    test('Handles collision with namespaces from glide-types', async () => {
        const vol = memfs.Volume.fromJSON({
            '/src/fluent/si.server.js': `function sample() { global.JSUtil(); }`,
            '/src/server/script.ts': `
                import { CatalogSI } from '@servicenow/glide/sn_cc';

                export function some() {
                    const appUtil = new CatalogSI();
                    appUtil.initialize();
                }
            `,
        })
        const fs = memfs.createFsFromVolume(vol) as FileSystem

        const project = new Project({
            fileSystem: fs as FileSystem,
            logger,
            rootDir: '/',
            config: NowConfig.parse({ scope: 'x_test', scopeId: GUID() }, logger),
            telemetryClient: telemetry,
        })

        const orchestrator = new Orchestrator(
            project,
            new MockConnector({
                syntaxEditorCompletionDefinitions: () => Promise.resolve(`declare class GlideRecord {}`),
                syntaxEditorCacheScriptIncludes: () =>
                    Promise.resolve({
                        'sn_cc.CatalogSI': '1e2e4e24c1af42bea7f0c0f9fa40fbeb',
                    }),
                syntaxEditorDefinitionsScriptIncludes: () =>
                    Promise.resolve({
                        '1e2e4e24c1af42bea7f0c0f9fa40fbeb': 'declare class CatalogSI{ initialize() }',
                    }),
            })
        )

        await orchestrator.types()

        expect(telemetry.startTimerEvent).toHaveBeenCalledWith('dependencies')
        expect(telemetry.sendEvent).toHaveBeenCalled()
        expect(telemetry.error).not.toHaveBeenCalled()

        const config = project.getConfig()

        const { typesDir } = config

        const serverDts = project.resolvePath(typesDir, 'augmented-script-includes.modules.d.ts')
        expect(FileSystem.existsSync(fs, serverDts)).toBeTruthy()
        const serverFileContent = fs.readFileSync(serverDts, { encoding: 'utf-8' })
        expect(serverFileContent).toBeDefined()
        expect(serverFileContent).toMatchInlineSnapshot(`
"import "@servicenow/glide/sn_cc";

declare module '@servicenow/glide/sn_cc' {
    class CatalogSI {
        initialize();
    }
}

"
`)
    })
})
